namespace NovaHarvest.Core.NPC; public enum NPCState{Unknown,Found,Rescued,LivingInColony,Missing} public sealed class NPC { public string Id{get;}public string Name{get;}public string Description{get;}public NPCProfession Profession{get;}public NPCSpecialization Specialization{get;}public NPCState State{get;private set;}=NPCState.Unknown;public NPCRelationship Relationship{get;} public string AbilityName{get;}public string AbilityDescription{get;}public IReadOnlyList<NPCService> Services{get;} public NPC(string id,string name,string description,NPCProfession profession,NPCSpecialization specialization,string abilityName,string abilityDescription,IEnumerable<NPCService>? services=null){if(string.IsNullOrWhiteSpace(id))throw new ArgumentException("ID inválido",nameof(id));if(string.IsNullOrWhiteSpace(name))throw new ArgumentException("Nome inválido",nameof(name));Id=id;Name=name;Description=description;Profession=profession;Specialization=specialization;AbilityName=abilityName;AbilityDescription=abilityDescription;Services=services?.ToList()??new List<NPCService>();Relationship=new NPCRelationship();} public bool Discover(){if(State!=NPCState.Unknown)return false;State=NPCState.Found;return true;}public bool Rescue(){if(State!=NPCState.Found)return false;State=NPCState.Rescued;return true;}public bool MoveToColony(){if(State!=NPCState.Rescued)return false;State=NPCState.LivingInColony;return true;}public void SetMissing()=>State=NPCState.Missing;public void IncreaseFriendship(int n)=>Relationship.IncreaseFriendship(n);public void DecreaseFriendship(int n)=>Relationship.DecreaseFriendship(n);public bool IsInColony()=>State==NPCState.LivingInColony;public bool HasService(string id)=>!string.IsNullOrWhiteSpace(id)&&Services.Any(x=>x.Id==id);}
